ALTER POLICY "feed_posts_social_insert_gate" ON "feed_posts" TO authenticated WITH CHECK ((app.tenant_role() = 'member' and visibility = 'followers' and community_id is null and (select app.social_enabled())) or (app.tenant_role() <> 'member' and visibility = 'tenant' and (community_id is null or exists (select 1 from public.communities c where c.id = community_id and c.tenant_id = app.tenant_id() and c.kind = 'organization'))) or (app.tenant_role() = 'member' and visibility = 'community' and community_id is not null and (select app.social_enabled()) and exists (select 1 from public.communities c where c.id = community_id and c.tenant_id = app.tenant_id() and c.kind = 'member' and c.created_by_user_id = app.user_id() and c.status = 'active' and c.deleted_at is null)) or (app.tenant_role() = 'member' and visibility = 'community' and community_id is not null and (select app.social_enabled()) and exists (select 1 from public.communities c where c.id = community_id and c.tenant_id = app.tenant_id() and c.kind = 'organization' and c.status = 'active' and c.deleted_at is null) and app.community_action_allowed(community_id, 'post')));